insert into public.categories(name,requires_credential) values
('Gasista',true),('Plomería',false),('Electricidad',true),('Herrería',false),('Albañilería',false),('Pintura',false),('Carpintería',false),('Cerrajería',false),('Calefacción',true),('Refrigeración',false),('Reparación de electrodomésticos',false),('Informática y soporte técnico',false),('Limpieza',false),('Jardinería',false),('Cuidado de personas',false),('Asistencia administrativa',false),('Fletes y mudanzas',false),('Mecánica',false),('Costura y arreglos',false),('Otros servicios',false) on conflict do nothing;
insert into public.skills(category_id,name) select id, skill from public.categories cross join lateral unnest(case name when 'Gasista' then array['Limpieza de calefón','Instalación de termotanque','Reparación de pérdidas','Prueba de hermeticidad'] when 'Plomería' then array['Cañerías','Grifería','Destapaciones'] when 'Electricidad' then array['Tableros','Instalaciones','Iluminación'] else array['Servicio general'] end) skill on conflict do nothing;
insert into public.rank_definitions(minimum_jobs,name) values (0,'Recién llegado'),(1,'Primer trabajo'),(5,'En marcha'),(15,'Activo'),(30,'Aprendiz'),(50,'Principiante'),(100,'Calificado'),(150,'Bronce'),(250,'Plata'),(400,'Oro'),(600,'Platino'),(850,'Diamante'),(1200,'Maestro'),(1750,'Gran Maestro'),(2500,'Leyenda') on conflict do nothing;
insert into public.app_settings(key,value) values ('fees','{"verified":0.05,"unverified":0.07}'),('ads','{"enabled":false,"provider":"mock"}'),('contact_policy','{"first":"block","second":"chat_suspend_24h","third":"profile_review"}') on conflict(key) do update set value=excluded.value;
